package com.adc.infrastructure;
import static org.junit.jupiter.api.Assertions.*;
import com.adc.application.*;
import com.adc.domain.shared.DomainFailure;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;

@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class AppointmentReschedulingIT {
    final AppointmentTransitionsIT fixture=new AppointmentTransitionsIT();AppointmentReschedulingService service;long target;
    @BeforeAll void migrate()throws Exception{fixture.migrate();}
    @AfterAll void dispose(){fixture.dispose();}
    @BeforeEach void setup()throws Exception{
        // Owned fixture cleanup only: break self-references before its existing DELETE sequence.
        // Keep the approved RESTRICT foreign key enabled throughout every business test.
        try(var connection=fixture.base().connection("inspector");var sql=connection.createStatement()){sql.execute("UPDATE adc_business.Appointment SET rescheduled_from_id=NULL WHERE rescheduled_from_id IS NOT NULL");}
        fixture.setup();var base=fixture.base();base.context.register(AppointmentReschedulingStore.class,AppointmentReschedulingService.class);service=base.context.getBean(AppointmentReschedulingService.class);base.db.update("INSERT INTO adc_identity.GrantCapability VALUES ('other','rescheduleAppointment')");
        base.db.update("INSERT INTO adc_business.Dentist (dentist_id,employee_number,full_name,date_of_birth,home_address,phone,email,hire_date,is_active,created_at,termination_date) VALUES (22,'D-22','Fictional replacement','1980-01-01',NULL,'000',NULL,'2020-01-01',true,?,NULL)",StaffAccountsIT.utc(base.now));base.db.update("INSERT INTO adc_business.DentistClinicAssignment VALUES (42,22,1,'2020-01-01',NULL,NULL,true)");target=Long.parseLong((String)fixture.fixture.fixture.schedules.create(fixture.command("createSchedule","target"),new ScheduleService.Creation(22,1,LocalDate.parse("2026-11-12"),LocalTime.of(9,0),LocalTime.of(10,0),20,null)).get("schedule_id"));
        fixture.fixture.fixture.schedules.suspend(fixture.command("suspendSchedule","suspend-source"),fixture.fixture.schedule,"临时停诊");
    }
    @AfterEach void close(){fixture.close();}
    AtomicCommandExecutor.Command command(String key){return fixture.command("rescheduleAppointment",key);}
    AppointmentReschedulingService.Choice choice(){return new AppointmentReschedulingService.Choice("RESCHEDULE","核实患者意向后改约",fixture.fixture.proof,1L,target,Instant.parse("2026-11-12T01:00:00Z"));}
    @SuppressWarnings("unchecked") @Test void oldAndNewSamePatientUniqueSourceEventsAndReplayAreAtomic()throws Exception{
        var result=service.reschedule(command("move"),fixture.id,choice());var old=(Map<String,Object>)result.get("old_appointment");var next=(Map<String,Object>)result.get("new_appointment");assertEquals("CLINIC_RESCHEDULE",old.get("cancellation_kind"));assertEquals("SCHEDULED",next.get("status"));assertEquals(old.get("patient_id"),next.get("patient_id"));assertEquals(Long.toString(fixture.id),next.get("rescheduled_from_id"));assertEquals(result,service.reschedule(command("move"),fixture.id,choice()));assertThrows(DomainFailure.class,()->service.reschedule(command("second-successor"),fixture.id,choice()));assertEquals(2,fixture.base().db.queryForObject("SELECT COUNT(*) FROM adc_business.AppointmentRequestedTreatment",Integer.class));assertEquals(3,fixture.base().db.queryForObject("SELECT COUNT(*) FROM adc_business.AppointmentEvent",Integer.class));
    }
    @Test void noAvailableOrInvalidTargetKeepsOldPendingAndClinicCancelHasNoSuccessor()throws Exception{
        fixture.base().db.update("UPDATE adc_business.DentistSchedule SET schedule_status='SUSPENDED' WHERE schedule_id=?",target);assertThrows(DomainFailure.class,()->service.reschedule(command("invalid-target"),fixture.id,choice()));assertEquals("SCHEDULED",fixture.base().db.queryForObject("SELECT status FROM adc_business.Appointment WHERE appointment_id=?",String.class,fixture.id));var result=service.reschedule(command("clinic-cancel"),fixture.id,new AppointmentReschedulingService.Choice("CLINIC_CANCEL","患者核实不再安排",fixture.fixture.proof,null,null,null));assertNull(result.get("new_appointment"));assertEquals("CLINIC_CANCEL",((Map<?,?>)result.get("old_appointment")).get("cancellation_kind"));
    }
    @Test void wrongBranchFieldsAndScopeAreRejected()throws Exception{
        assertThrows(DomainFailure.class,()->service.reschedule(command("missing"),fixture.id,new AppointmentReschedulingService.Choice("RESCHEDULE","fixture",fixture.fixture.proof,null,null,null)));assertThrows(DomainFailure.class,()->service.reschedule(command("forbidden"),fixture.id,new AppointmentReschedulingService.Choice("CLINIC_CANCEL","fixture",fixture.fixture.proof,1L,target,Instant.parse("2026-11-12T01:00:00Z"))));assertThrows(DomainFailure.class,()->service.reschedule(command("wrong-proof"),fixture.id,new AppointmentReschedulingService.Choice("RESCHEDULE","fixture","untrusted",1L,target,Instant.parse("2026-11-12T01:00:00Z"))));
    }
    @Test void auditFailureCannotLeaveCancelledSourceOrOrphanSuccessor()throws Exception{
        try(var connection=fixture.base().connection("inspector");var sql=connection.createStatement()){sql.execute("REVOKE INSERT ON adc_audit.* FROM 'adc_runtime_role'");try{assertThrows(org.springframework.dao.DataAccessException.class,()->service.reschedule(command("rollback"),fixture.id,choice()));}finally{sql.execute("GRANT INSERT ON adc_audit.* TO 'adc_runtime_role'");}}
        assertEquals("SCHEDULED",fixture.base().db.queryForObject("SELECT status FROM adc_business.Appointment WHERE appointment_id=?",String.class,fixture.id));assertEquals(1,fixture.base().db.queryForObject("SELECT COUNT(*) FROM adc_business.Appointment",Integer.class));assertEquals(1,fixture.base().db.queryForObject("SELECT COUNT(*) FROM adc_business.AppointmentEvent",Integer.class));
    }
    @Test void failuresAtNewAppointmentSourceLinkAndBookEventRollbackBothEnds()throws Exception{
        var triggers=List.of("BEFORE INSERT ON adc_business.Appointment FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='owned successor failure'","BEFORE UPDATE ON adc_business.Appointment FOR EACH ROW BEGIN IF NEW.rescheduled_from_id IS NOT NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='owned link failure'; END IF; END","BEFORE INSERT ON adc_business.AppointmentEvent FOR EACH ROW BEGIN IF NEW.event_type='BOOK' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='owned event failure'; END IF; END");int index=0;
        for(String trigger:triggers){String key="failure-stage-"+index++;try(var connection=fixture.base().connection("inspector");var sql=connection.createStatement()){sql.execute("CREATE TRIGGER adc_business.adc_test_reschedule_failure "+trigger);try{assertThrows(org.springframework.dao.DataAccessException.class,()->service.reschedule(command(key),fixture.id,choice()));}finally{sql.execute("DROP TRIGGER adc_business.adc_test_reschedule_failure");}}assertEquals("SCHEDULED",fixture.base().db.queryForObject("SELECT status FROM adc_business.Appointment WHERE appointment_id=?",String.class,fixture.id));assertEquals(1,fixture.base().db.queryForObject("SELECT COUNT(*) FROM adc_business.Appointment",Integer.class));assertEquals(1,fixture.base().db.queryForObject("SELECT COUNT(*) FROM adc_business.AppointmentEvent",Integer.class));}
    }
    @Test void differentOldAppointmentsAndReviewersCompeteForOneNewSlotWithoutPartialCancellation()throws Exception{
        var base=fixture.base();long other=Crypto.id();base.db.update("INSERT INTO adc_business.Appointment (appointment_id,patient_id,clinic_id,dentist_id,schedule_id,scheduled_at,status,created_at,updated_at) SELECT ?,patient_id,clinic_id,dentist_id,schedule_id,DATE_ADD(scheduled_at,INTERVAL 20 MINUTE),'SCHEDULED',created_at,updated_at FROM adc_business.Appointment WHERE appointment_id=?",other,fixture.id);base.db.update("INSERT INTO adc_business.AppointmentRequestedTreatment VALUES (?,71,NULL)",other);base.db.update("INSERT INTO adc_business.AppointmentEvent VALUES (?,?,'BOOK',NULL,'SCHEDULED',?,'RECEPTION','other',NULL,'owned-history',NULL)",Crypto.id(),other,StaffAccountsIT.utc(base.now));base.db.update("UPDATE adc_identity.AccessGrant SET role_code='RECEPTION' WHERE grant_id='hq'");for(String capability:List.of("getPatient","rescheduleAppointment"))base.db.update("INSERT INTO adc_identity.GrantCapability VALUES ('hq',?)",capability);
        var lookup=fixture.fixture.patients.lookup(new AtomicCommandExecutor.Command(base.token,"WEB","lookupPatient","hq-verify",Crypto.sha256("hq-verify"),UUID.randomUUID().toString()),(String)fixture.fixture.patient.get("patient_number"),LocalDate.parse("1990-01-02"),new PatientService.Verification(1,true,"manual second reviewer"));var secondChoice=new AppointmentReschedulingService.Choice("RESCHEDULE","核实另一原约改约",(String)lookup.get("verification_reference"),1L,target,Instant.parse("2026-11-12T01:00:00Z"));
        try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{start.await();try{service.reschedule(command("race-first"),fixture.id,choice());return 200;}catch(DomainFailure failure){return failure.status();}});var b=pool.submit(()->{start.await();try{service.reschedule(new AtomicCommandExecutor.Command(base.token,"WEB","rescheduleAppointment","race-second",Crypto.sha256("race-second"),UUID.randomUUID().toString()),other,secondChoice);return 200;}catch(DomainFailure failure){return failure.status();}});start.countDown();var results=new ArrayList<>(List.of(a.get(20,java.util.concurrent.TimeUnit.SECONDS),b.get(20,java.util.concurrent.TimeUnit.SECONDS)));Collections.sort(results);assertEquals(List.of(200,409),results);}
        assertEquals(1,base.db.queryForObject("SELECT COUNT(*) FROM adc_business.Appointment WHERE schedule_id=? AND status='SCHEDULED'",Integer.class,target));assertEquals(1,base.db.queryForObject("SELECT COUNT(*) FROM adc_business.Appointment WHERE schedule_id=? AND status='SCHEDULED'",Integer.class,fixture.fixture.schedule));assertEquals(1,base.db.queryForObject("SELECT COUNT(*) FROM adc_business.Appointment WHERE rescheduled_from_id IS NOT NULL",Integer.class));
    }
    @Test void controllerRejectsExplicitNullTargetInClinicCancelWithoutContractDrift()throws Exception{
        var controller=new com.adc.interfaces.AppointmentReschedulingController(service,fixture.base().context.getBean(com.adc.identity.AuthSecrets.class));var mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup(controller).setControllerAdvice(new com.adc.interfaces.ApiErrors()).build();
        String body="{\"action\":\"CLINIC_CANCEL\",\"reason\":\"fixture\",\"verification_reference\":\""+fixture.fixture.proof+"\",\"new_clinic_id\":null}";
        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/appointments/"+fixture.id+"/reschedule").cookie(new jakarta.servlet.http.Cookie("adc_session",fixture.base().other)).header("Idempotency-Key","explicit-null").contentType("application/json").content(body)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isUnprocessableEntity());assertEquals("SCHEDULED",fixture.base().db.queryForObject("SELECT status FROM adc_business.Appointment WHERE appointment_id=?",String.class,fixture.id));
    }
}
